from fractions import Fraction


def station_outcomes(kernel):
    """Return per-station success probability and conditional mean time.

    Solves the absorbing Markov chain exactly using rational arithmetic.
    For each station s, let p_s be the probability of eventual successful
    delivery and m_s the expected total transit time conditional on success
    (0 for delivered stations, None when p_s == 0).

    Equations (for non-delivered stations):
        p_s = sum_r w_r * p_target
        m_s = (sum_r w_r * (time_r + m_target) * p_target) / p_s
    where w_r is the normalized route probability. Stations that cannot reach
    a delivered station have p_s = 0 and m_s = None.
    """
    stations = kernel["stations"]
    delivered = set(kernel["delivered"])
    outgoing = kernel["outgoing"]
    can_deliver = set(kernel["can_deliver"])

    # Success probabilities: solve linear system over the can_deliver set.
    # Delivered stations have p = 1. Non-delivered stations in can_deliver
    # satisfy p_s = sum_r w_r * p_target.
    p = {}
    for s in stations:
        if s in delivered:
            p[s] = Fraction(1)
        elif s not in can_deliver:
            p[s] = Fraction(0)
        else:
            p[s] = None  # to be solved

    # Build and solve the linear system for unknown p values.
    unknown = [s for s in stations if p[s] is None]
    if unknown:
        idx = {s: i for i, s in enumerate(unknown)}
        n = len(unknown)
        # Matrix A (n x n) and vector b.
        A = [[Fraction(0) for _ in range(n)] for _ in range(n)]
        b = [Fraction(0) for _ in range(n)]
        for s in unknown:
            i = idx[s]
            A[i][i] = Fraction(1)
            for target, prob, _time in outgoing.get(s, []):
                if target in delivered:
                    b[i] += prob * Fraction(1)
                elif target in idx:
                    A[i][idx[target]] -= prob
                # target not in can_deliver contributes 0
        # Gaussian elimination with exact fractions.
        for col in range(n):
            # find pivot
            pivot = None
            for r in range(col, n):
                if A[r][col] != 0:
                    pivot = r
                    break
            if pivot is None:
                continue
            if pivot != col:
                A[col], A[pivot] = A[pivot], A[col]
                b[col], b[pivot] = b[pivot], b[col]
            inv = Fraction(1) / A[col][col]
            for c in range(col, n):
                A[col][c] *= inv
            b[col] *= inv
            for r in range(n):
                if r != col and A[r][col] != 0:
                    factor = A[r][col]
                    for c in range(col, n):
                        A[r][c] -= factor * A[col][c]
                    b[r] -= factor * b[col]
        for s in unknown:
            p[s] = b[idx[s]]

    # Conditional mean times. For delivered stations m = 0. For stations with
    # p = 0, m = None. Otherwise solve:
    #   p_s * m_s = sum_r w_r * p_target * (time_r + m_target)
    # Let q_s = p_s * m_s. Then q_s = sum_r w_r * (p_target * time_r + q_target).
    q = {}
    for s in stations:
        if s in delivered:
            q[s] = Fraction(0)
        elif p[s] == 0:
