    a delivered station have p_s = 0 and m_s = None.
    """
    stations = kernel["stations"]
    delivered = set(kernel["delivered"])
    outgoing = kernel["outgoing"]
    can_deliver = set(kernel["can_deliver"])

    # Success probabilities: solve linear system over the can_deliver set.
    # Delivered stations have p = 1. Non-delivered stations in can_deliver
    # satisfy p_s = sum_r w_r * p_target.
    p = {}
    for s in stations:
        if s in delivered:
            p[s] = Fraction(1)
        elif s not in can_deliver:
            p[s] = Fraction(0)
        else:
            p[s] = None  # to be solved

