            for c in range(col, n):
                A[col][c] *= inv
            b[col] *= inv
            for r in range(n):
                if r != col and A[r][col] != 0:
                    factor = A[r][col]
                    for c in range(col, n):
                        A[r][c] -= factor * A[col][c]
                    b[r] -= factor * b[col]
