from runtime import build, read
from packages.analysis.routing_model import routing_kernel
from packages.analysis.delivery_outcomes import station_outcomes


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    kernel = routing_kernel(request)
    outcomes = station_outcomes(kernel)
    return {"stations": outcomes}


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

import unittest
from fractions import Fraction

API_BOUNDARY_REQUIREMENTS = [
    {
        "target_path": "packages/analysis/engine.py",
        "function": "transform",
        "rules": {
            "nonfinite_unknown_field": {
                "applicable": False,
                "contract_path": "packages/analysis/SPEC.md",
                "requirement_quote": "All weights and travel times are positive integers.",
                "reason": "SPEC.md does not require ValueError for non-finite or unknown fields.",
            },
            "invalid_payload_type": {
                "applicable": False,
                "contract_path": "packages/analysis/SPEC.md",
                "requirement_quote": "stations lists all routing states, delivered lists successful terminal stations, and routes contains directed rows {from,to,weight,time}.",
                "reason": "SPEC.md does not require ValueError for invalid payload types.",
            },
        },
    },
]


class TestDeliveryOutcomes(unittest.TestCase):
    def test_public_example(self):
        payload = {
            "request": {
                "stations": ["A", "B", "OK", "Return"],
                "delivered": ["OK"],
                "routes": [
                    {"from": "A", "to": "B", "weight": 1, "time": 4},
                    {"from": "A", "to": "Return", "weight": 1, "time": 1},
                    {"from": "B", "to": "B", "weight": 1, "time": 2},
                    {"from": "B", "to": "OK", "weight": 1, "time": 3},
                ],
            }
        }
        result = call_candidate("packages/analysis/engine.py", "transform", args=[payload, {}])
        self.assertEqual(result["stations"]["A"]["success"], [1, 2])
        self.assertEqual(result["stations"]["A"]["mean_if_success"], [9, 1])
        self.assertEqual(result["stations"]["B"]["success"], [1, 1])
        self.assertEqual(result["stations"]["B"]["mean_if_success"], [5, 1])
        self.assertEqual(result["stations"]["OK"]["success"], [1, 1])
        self.assertEqual(result["stations"]["OK"]["mean_if_success"], [0, 1])
        self.assertEqual(result["stations"]["Return"]["success"], [0, 1])
        self.assertIsNone(result["stations"]["Return"]["mean_if_success"])

    def test_loop_and_dead_end(self):
        # S self-loop 1/2 time 2, S->T 1/4 time 5, S->D 1/4 time 11.
        # success = 1/2, conditional mean = 7.
        payload = {
            "request": {
                "stations": ["S", "T", "D"],
                "delivered": ["T"],
                "routes": [
                    {"from": "S", "to": "S", "weight": 2, "time": 2},
                    {"from": "S", "to": "T", "weight": 1, "time": 5},
                    {"from": "S", "to": "D", "weight": 1, "time": 11},
                ],
            }
        }
        result = call_candidate("packages/analysis/engine.py", "transform", args=[payload, {}])
        self.assertEqual(result["stations"]["S"]["success"], [1, 2])
        self.assertEqual(result["stations"]["S"]["mean_if_success"], [7, 1])
        self.assertEqual(result["stations"]["T"]["success"], [1, 1])
        self.assertEqual(result["stations"]["T"]["mean_if_success"], [0, 1])
        self.assertEqual(result["stations"]["D"]["success"], [0, 1])
        self.assertIsNone(result["stations"]["D"]["mean_if_success"])

    def test_parallel_routes_normalization(self):
        payload = {
            "request": {
                "stations": ["S", "T", "D"],
                "delivered": ["T"],
                "routes": [
                    {"from": "S", "to": "T", "weight": 1, "time": 2},
                    {"from": "S", "to": "T", "weight": 3, "time": 6},
                    {"from": "S", "to": "D", "weight": 2, "time": 9},
                    {"from": "D", "to": "D", "weight": 1, "time": 1},
                ],
            }
        }
        result = call_candidate("packages/analysis/engine.py", "transform", args=[payload, {}])
        # S: success = (1/6 + 1/2) = 2/3; conditional mean = weighted time / success
        #   = (1/6*2 + 1/2*6) / (2/3) = (1/3 + 3) / (2/3) = (10/3)/(2/3) = 5
        self.assertEqual(result["stations"]["S"]["success"], [2, 3])
        self.assertEqual(result["stations"]["S"]["mean_if_success"], [5, 1])
        self.assertEqual(result["stations"]["T"]["success"], [1, 1])
        self.assertEqual(result["stations"]["D"]["success"], [0, 1])
        self.assertIsNone(result["stations"]["D"]["mean_if_success"])

    def test_transform_returns_stations(self):
        payload = {
            "request": {
                "stations": ["A", "B", "OK", "Return"],
                "delivered": ["OK"],
                "routes": [
                    {"from": "A", "to": "B", "weight": 1, "time": 4},
                    {"from": "A", "to": "Return", "weight": 1, "time": 1},
                    {"from": "B", "to": "B", "weight": 1, "time": 2},
                    {"from": "B", "to": "OK", "weight": 1, "time": 3},
                ],
            }
        }
        result = call_candidate("packages/analysis/engine.py", "transform", args=[payload, {}])
        self.assertIsInstance(result, dict)
        self.assertEqual(set(result.keys()), {"stations"})
        self.assertEqual(set(result["stations"].keys()), {"A", "B", "OK", "Return"})
        # caller input unchanged
        self.assertEqual(payload["request"]["stations"], ["A", "B", "OK", "Return"])


if __name__ == "__main__":
    unittest.main()
